// Lote autoral: cada item traz cinco justificativas específicas, uma por alternativa.
import fs from 'node:fs';
const EDITAL='https://servidor-arquivos.ibfc.org.br/arquivos-publicos/edital-01-2026-ibfc-11.06-final-marcadores.pdf';
const TEC='https://anexos.cdn.selecao.net.br/uploads/747/concursos/423/anexos/c3b6eba1-4aa5-4320-9af8-adc570bcc26c.pdf';
const CERT='https://cartilha.cert.br/';
const ALL=['aca','aci','aor','acr','acs'], MAN=['aor','acr','acs'], TECH=['acr','acs'];
const B=[];
function add(subject,topic,roles,statement,options,notes,locator='Anexo IV',url=EDITAL,difficulty='hard') {
  if(options.length!==5||notes.length!==5)throw new Error('Cinco alternativas e justificativas obrigatórias');
  const answer=B.length%5;
  const order=[1,2,3,4]; order.splice(answer,0,0);
  B.push({id:`ibge26-b010-${String(B.length+1).padStart(3,'0')}`,roles,subject,topic,difficulty,statement,
    options:order.map(i=>options[i]),answer,
    explanation:notes[0]+' '+notes.slice(1).join(' '),whyWrong:order.map(i=>notes[i]),
    sources:[{title:url===TEC?'Estudo dos conhecimentos técnicos para o 12º Censo Agropecuário, Florestal e Aquícola':url===CERT?'Cartilha de Segurança para Internet — CERT.br':'Edital nº 01/2026 — conteúdo programático',locator,url}],status:'approved'});
}
const P=(topic,statement,options,notes)=>add('Língua Portuguesa',topic,ALL,statement,options,notes,'Anexo IV — Língua Portuguesa');
const L=(topic,statement,options,notes)=>add('Raciocínio Lógico Quantitativo',topic,ALL,statement,options,notes,'Anexo IV — Raciocínio Lógico Quantitativo');
const A=(topic,statement,options,notes)=>add('Noções de Administração',topic,['aca'],statement,options,notes,'Anexo IV — Noções de Administração');
const G=(topic,statement,options,notes)=>add('Noções de Administração/Situações Gerenciais',topic,MAN,statement,options,notes,'Anexo IV — Situações Gerenciais');
const T=(topic,page,statement,options,notes)=>add('Conhecimentos Técnicos',topic,TECH,statement,options,notes,`p. ${page}`,TEC);
const I=(topic,statement,options,notes)=>add('Noções de Informática',topic,['aci'],statement,options,notes,'Anexo IV — Noções de Informática');
const N=(topic,statement,options,notes)=>add('Noções Básicas de Informática',topic,['aor'],statement,options,notes,'Anexo IV — Noções Básicas de Informática');

// Língua Portuguesa — 20 questões independentes, com textos próprios.
P('interpretação de texto','Leia: “O posto ampliou o atendimento, mas manteve a mesma equipe. O ganho veio da redistribuição das visitas.” Qual inferência é sustentada pelo trecho, sem acrescentar uma causa não informada?',
 ['A organização do trabalho contribuiu para ampliar o atendimento.','A equipe foi ampliada após o aumento das visitas.','A tecnologia substituiu parte dos agentes.','O posto reduziu a duração de cada entrevista.','O ganho decorreu exclusivamente de horas extras.'],
 ['O texto atribui o ganho à redistribuição das visitas, isto é, a uma mudança de organização.','O trecho diz que a equipe permaneceu a mesma.','Não há menção a tecnologia ou substituição de pessoas.','A duração das entrevistas não é informada.','Horas extras não aparecem como explicação no texto.']);
P('coesão referencial','No comunicado “A equipe enviou os mapas aos supervisores depois que eles concluíram a conferência”, a redação deve deixar claro que a conferência foi feita pelos supervisores. Qual reescrita elimina a ambiguidade?',
 ['Após os supervisores concluírem a conferência, a equipe lhes enviou os mapas.','A equipe enviou os mapas aos supervisores depois que eles concluíram a conferência.','Depois de concluírem a conferência, eles receberam os mapas da equipe.','A equipe, depois que concluíram a conferência, enviou-lhes os mapas.','Os mapas foram enviados depois da conferência deles pelos supervisores.'],
 ['O sujeito explícito “os supervisores” identifica quem concluiu a conferência e “lhes” retoma esse grupo.','O pronome “eles” ainda pode recuperar mais de um antecedente.','O sujeito de “concluírem” fica implícito e “eles” não resolve a referência.','Há desajuste entre “a equipe” singular e “concluíram” plural, além da ambiguidade.','A construção final deixa incerta a relação entre “deles” e “supervisores”.']);
P('pontuação e sentido','Compare “Os agentes que receberam o mapa digital iniciarão amanhã” com “Os agentes, que receberam o mapa digital, iniciarão amanhã”. Qual interpretação da segunda frase é adequada?',
 ['As vírgulas apresentam o recebimento do mapa como informação acessória sobre todos os agentes mencionados.','As vírgulas restringem o início aos agentes que receberam o mapa.','As duas frases têm obrigatoriamente o mesmo alcance de “agentes”.','A segunda frase afirma que nenhum agente recebeu o mapa.','As vírgulas transformam “receberam” em verbo principal da oração.'],
 ['A oração entre vírgulas é explicativa; no contexto, comenta o grupo de agentes já identificado.','A restrição caracteriza a versão sem vírgulas, na qual apenas parte do grupo é selecionada.','A presença ou ausência das vírgulas altera o alcance da oração relativa.','A segunda oração afirma, e não nega, o recebimento do mapa.','O verbo principal continua sendo “iniciarão”; “receberam” integra a oração relativa.']);
P('regência verbal','Um aviso formal precisa registrar que a supervisora informou aos agentes a mudança de horário. Qual redação mantém a regência e o sentido, sem trocar destinatário por objeto informado?',
 ['A supervisora informou os agentes da mudança de horário.','A supervisora informou aos agentes de que o horário mudou.','A supervisora informou à mudança de horário aos agentes.','A supervisora informou os agentes para a mudança de horário.','A supervisora informou na mudança os agentes.'],
 ['“Informar alguém de algo” é construção aceita: agentes são destinatários e mudança é o conteúdo.','A construção cruza “informou aos agentes que” com “informou os agentes de que”.','A mudança é o conteúdo, não destinatário introduzido por “a”.','A preposição “para” não exprime adequadamente o conteúdo da informação nesse verbo.','“Na mudança” não estabelece a relação de regência pedida.']);
P('concordância verbal','Num relatório, lê-se: “Mais de um recenseador ___ a inconsistência, mas apenas um deles ___ o chamado”. Quais formas completam corretamente, pela regra geral de concordância?',
 ['identificou; registrou','identificaram; registraram','identificou; registraram','identificaram; registrou','identificara; registraram'],
 ['“Mais de um” leva, em regra, o verbo ao singular; “apenas um deles” também determina singular.','O plural nas duas lacunas ignora os núcleos singulares das expressões usadas.','A segunda forma não concorda com “um deles”.','A primeira forma não segue a concordância geral de “mais de um”.','A primeira forma altera o tempo verbal e a segunda mantém discordância com “um”.']);
P('crase','Assinale a redação em que o sinal indicativo de crase é exigido pela combinação de preposição e artigo, sem depender de um nome próprio facultativo.',
 ['O registro foi encaminhado à supervisão antes do encerramento do turno.','O registro foi encaminhado à cada supervisor da unidade.','O registro foi encaminhado à uma equipe de apoio.','O registro foi encaminhado à todos os servidores.','O registro foi encaminhado à quem revisou o mapa.'],
 ['“Encaminhado a” exige preposição, e “a supervisão” admite artigo feminino; a fusão produz “à”.','Não se usa artigo feminino antes do pronome indefinido “cada”.','O artigo indefinido “uma” não se funde com a preposição “a” nessa construção.','“Todos” é masculino plural, incompatível com a forma singular feminina “à”.','O pronome “quem” não recebe artigo feminino que justifique a crase.']);
P('valor semântico','No registro “Embora houvesse conexão, os dados permaneceram no aparelho”, qual relação o conectivo estabelece entre as duas informações?',
 ['Concessão: a conexão criava expectativa de transmissão, mas ela não se concretizou.','Causa: a conexão provocou a permanência dos dados.','Condição: os dados só ficariam no aparelho se houvesse conexão.','Conclusão: a permanência prova que a conexão foi criada.','Finalidade: a conexão existia para manter os dados localmente.'],
 ['“Embora” introduz fato admitido que não impede o resultado contrário à expectativa.','A frase não diz que a conexão causou o armazenamento local.','Não há estrutura condicional do tipo “se... então”.','O enunciado não conclui a existência da conexão a partir do armazenamento.','Nenhuma finalidade ou intenção é expressa pelo conectivo.']);
P('voz passiva analítica','Transforme sem alterar o tempo verbal nem o sentido: “A equipe havia conferido os formulários antes da transmissão”. Qual versão passiva é adequada?',
 ['Os formulários haviam sido conferidos pela equipe antes da transmissão.','Os formulários foram conferidos pela equipe antes da transmissão.','Os formulários eram conferidos pela equipe antes da transmissão.','A equipe tinha sido conferida pelos formulários antes da transmissão.','Os formulários haveriam de conferir a equipe antes da transmissão.'],
 ['O objeto “os formulários” vira sujeito paciente e “haviam sido conferidos” preserva o pretérito mais-que-perfeito composto.','“Foram conferidos” altera a relação temporal expressa por “havia conferido”.','“Eram conferidos” sugere ação habitual ou em curso, não anterioridade concluída.','A inversão dos participantes faz dos formulários agentes da conferência.','A construção final não é passiva equivalente e atribui ação aos formulários.']);
P('parônimos','Em um ofício, o agente pretende dizer que corrigiu um dado anteriormente registrado de modo equivocado. Qual verbo exprime a correção, e não a confirmação do dado?',
 ['Retificar o dado.','Ratificar o dado.','Reiterar o dado.','Referendar o dado.','Reproduzir o dado.'],
 ['“Retificar” é corrigir; no contexto, substitui ou ajusta o registro incorreto.','“Ratificar” é confirmar, exatamente o oposto da correção pretendida.','“Reiterar” é repetir, sem corrigir o conteúdo.','“Referendar” é aprovar ou validar, não alterar o dado equivocado.','“Reproduzir” é copiar ou repetir o conteúdo anterior.']);
P('acentuação','Um comunicado contém as palavras “saída”, “juízo”, “raiz” e “juiz”. Qual análise explica o acento das duas primeiras sem acentuar indevidamente as duas últimas?',
 ['O i tônico fica isolado na sílaba de “saída” e “juízo”, mas não na de “raiz” e “juiz”.','Toda palavra terminada em “iz” recebe acento gráfico.','O acento depende apenas de a palavra ter duas sílabas.','“Raiz” e “juiz” deveriam receber acento por terminarem em z.','“Saída” e “juízo” são acentuadas por serem proparoxítonas.'],
 ['A regra do hiato acentua i/u tônicos isolados ou seguidos de s na sílaba; em “raiz” e “juiz”, o z integra a sílaba.','A terminação “iz” não produz essa regra de acentuação.','Número de sílabas, isoladamente, não justifica o acento apresentado.','O z após o i impede aplicar a regra do i isolado nesses casos.','Nenhuma das duas palavras destacadas tem tonicidade proparoxítona.']);
P('pontuação de adjunto deslocado','Um relatório começa por um adjunto adverbial longo: “Após a conferência dos limites descritos no mapa digital os agentes iniciaram as visitas”. Qual revisão melhora a marcação sintática?',
 ['Após a conferência dos limites descritos no mapa digital, os agentes iniciaram as visitas.','Após, a conferência dos limites descritos no mapa digital os agentes iniciaram as visitas.','Após a conferência dos limites descritos no mapa digital os agentes, iniciaram as visitas.','Após a conferência, dos limites descritos no mapa digital os agentes iniciaram as visitas.','Após a conferência dos limites descritos no mapa digital, os agentes, iniciaram as visitas.'],
 ['A vírgula após o adjunto longo deslocado separa a circunstância inicial da oração principal.','A vírgula após “Após” rompe a locução prepositiva e seu complemento.','A vírgula entre sujeito “os agentes” e verbo “iniciaram” é indevida.','A pausa separa “conferência” de seu complemento “dos limites”.','A segunda vírgula isola indevidamente o sujeito do predicado.']);
P('concordância com haver','No sentido de existir, o verbo “haver” é impessoal. Qual forma corrige o trecho “Haviam dois mapas pendentes e houveram três alterações” mantendo os tempos?',
 ['Havia dois mapas pendentes e houve três alterações.','Haviam dois mapas pendentes e houve três alterações.','Havia dois mapas pendentes e houveram três alterações.','Houvera dois mapas pendentes e houve três alterações.','Haviam dois mapas pendentes e houveram três alterações.'],
 ['“Haver” existencial fica na terceira pessoa do singular: “havia” e “houve”, mesmo com complementos plurais.','A primeira forma segue indevidamente o plural de “mapas”.','A segunda forma segue indevidamente o plural de “alterações”.','“Houvera” muda o tempo verbal original da primeira oração.','As duas flexões plurais tratam objetos como sujeitos de verbo impessoal.']);
P('coesão causal e adversativa','Leia: “O arquivo estava íntegro; contudo, a transmissão falhou”. Qual substituição mantém a oposição expressa por “contudo”, sem converter a relação em causa ou conclusão?',
 ['O arquivo estava íntegro; entretanto, a transmissão falhou.','O arquivo estava íntegro; portanto, a transmissão falhou.','O arquivo estava íntegro; porque a transmissão falhou.','O arquivo estava íntegro; logo, a transmissão falhou.','O arquivo estava íntegro; visto que a transmissão falhou.'],
 ['“Entretanto” é adversativo como “contudo” e preserva o contraste entre integridade e falha.','“Portanto” introduz conclusão, não oposição.','“Porque” marca causa e não mantém a relação adversativa.','“Logo” também apresenta uma conclusão não afirmada no original.','“Visto que” tem valor causal e desloca o sentido da frase.']);
P('regência nominal','Em “A equipe está atenta ___ mudanças no cronograma e apta ___ executar o novo roteiro”, qual preenchimento respeita a regência nominal e a forma adequada dos complementos?',
 ['às; a','as; à','à; as','às; à','as; a'],
 ['“Atenta a” mais artigo plural “as” resulta em “às”; “apta a” antes de infinitivo não recebe artigo.','Falta a preposição exigida por “atenta” e sobra crase antes do infinitivo.','“Mudanças” é plural, de modo que “à” singular não concorda; “apta” exige preposição.','Há crase indevida antes do verbo “executar”.','Falta a preposição fundida ao artigo antes de “mudanças”.']);
P('ambiguidade','A frase “O supervisor encontrou o agente com o mapa” permite duas leituras. Qual reescrita afirma inequivocamente que o agente portava o mapa?',
 ['O supervisor encontrou o agente que portava o mapa.','Com o mapa, o supervisor encontrou o agente.','O supervisor encontrou com o mapa o agente.','O supervisor, com o mapa, encontrou o agente.','O agente encontrou o supervisor com o mapa.'],
 ['A oração “que portava o mapa” liga o objeto diretamente ao agente.','O termo deslocado tende a ligar o mapa ao supervisor.','“Com o mapa” ainda admite ligação à ação ou ao supervisor.','A intercalação atribui explicitamente o mapa ao supervisor.','Além de inverter quem encontrou quem, mantém ambiguidade sobre quem portava o mapa.']);
P('ortografia','Um registro administrativo deve empregar corretamente “sessão”, “seção” e “cessão”. Qual frase usa as três formas de acordo com seus sentidos?',
 ['A seção de mapas solicitou a cessão do equipamento durante a sessão de treinamento.','A sessão de mapas solicitou a seção do equipamento durante a cessão de treinamento.','A cessão de mapas solicitou a sessão do equipamento durante a seção de treinamento.','A seção de mapas solicitou a sessão do equipamento durante a cessão de treinamento.','A cessão de mapas solicitou a seção do equipamento durante a sessão de treinamento.'],
 ['“Seção” é unidade ou divisão; “cessão” é transferência; “sessão” é reunião ou período de atividade.','“Sessão” não nomeia a unidade de mapas, e “seção” não descreve transferência do equipamento.','“Cessão” não designa a unidade, e “sessão” não designa o ato de ceder.','A reunião não é “cessão” e o empréstimo não é “sessão”.','A primeira palavra não designa a unidade de mapas e a segunda não nomeia a transferência.']);
P('colocação pronominal','Em uma comunicação formal, qual frase usa a colocação do pronome de modo compatível com a palavra atrativa presente na oração?',
 ['Nunca se divulgam dados individuais dos informantes.','Nunca divulgam-se dados individuais dos informantes.','Não divulgam-se dados individuais dos informantes.','Jamais divulgar-se-ão dados individuais dos informantes.','Quem informou-me sobre os dados individuais?'],
 ['O advérbio negativo “nunca” atrai o pronome para antes do verbo, justificando “se divulgam”.','A ênclise depois de “nunca” contraria a atração pela negativa.','“Não” também exige próclise nesse contexto.','“Jamais” atrai o pronome e impede a mesóclise apresentada.','O pronome relativo/interrogativo “quem” atrai “me”: “Quem me informou?”.']);
P('reescrita','Considere o aviso: “Se faltar conexão, registre os dados localmente; transmita-os quando ela voltar”. Qual reescrita preserva a ordem das ações e o referente do pronome?',
 ['Na ausência de conexão, registre os dados no aparelho e transmita-os quando a conexão for restabelecida.','Na ausência de conexão, deixe de registrar dados até que a conexão retorne.','Transmita os dados antes de registrá-los, caso a conexão retorne.','Quando os dados voltarem, registre a conexão localmente e transmita-a.','Registre a conexão no aparelho, embora os dados não possam ser transmitidos.'],
 ['O registro local ocorre primeiro; a transmissão vem depois do restabelecimento da conexão.','O aviso manda registrar mesmo sem conexão, não suspender o trabalho.','A transmissão não antecede o registro no procedimento original.','“Ela” retoma conexão, não os dados, e a sequência foi invertida.','O objeto do registro são dados, não a própria conexão.']);
P('inferência textual','Leia: “O mapa sugere um acesso mais curto. Entretanto, o descritivo situa a ponte fora do setor”. Qual decisão é compatível com as duas frases, sem tratar sugestão visual como limite oficial?',
 ['Conferir o limite pelo descritivo antes de usar o acesso sugerido pelo mapa.','Tomar o acesso mais curto como prova de que a ponte pertence ao setor.','Ignorar o descritivo porque um mapa sempre o substitui.','Concluir que a ponte foi removida da área após a impressão do mapa.','Alterar o limite do setor para incluir a ponte e encurtar o trajeto.'],
 ['O contraste introduzido por “entretanto” exige considerar a informação textual sobre o limite antes de decidir a rota.','A facilidade de acesso não demonstra pertencimento territorial.','O trecho não autoriza descartar o descritivo em favor da aparência visual.','Não há dado sobre alteração física da ponte ou data do mapa.','Uma rota conveniente não autoriza redefinir limites oficiais.']);
P('paralelismo sintático','Uma lista de tarefas diz “Conferir mapas, a atualização de cadastros e que os dados sejam enviados”. Qual reescrita usa estruturas paralelas sem perder as três ações?',
 ['Conferir mapas, atualizar cadastros e enviar dados.','Conferir mapas, cadastros atualizados e que os dados sejam enviados.','A conferência de mapas, atualizar cadastros e envio de dados.','Conferir mapas, a atualização de cadastros e enviar dados.','Mapas conferidos, atualizar cadastros e dados enviados.'],
 ['Os três infinitivos coordenados nomeiam ações no mesmo formato e preservam o conteúdo da lista.','Mistura verbo, grupo nominal e oração subordinada.','Mistura nominalização, verbo e grupo nominal.','Alterna infinitivo, grupo nominal e infinitivo, quebrando o paralelismo.','Mistura particípios e infinitivo, além de não formular três comandos equivalentes.']);

// Raciocínio lógico quantitativo — 15 questões.
L('conjuntos','De 90 formulários, 48 tinham a marca A, 37 a marca B e 15 tinham ambas. Quantos não tinham nenhuma das duas marcas?',
 ['20','5','15','25','35'],
 ['A união tem 48+37−15=70 formulários; os restantes são 90−70=20.','Somar a interseção duas vezes superestima a união e produz resto incorreto.','Quinze é a interseção informada, não o complemento da união.','Vinte e cinco não resulta de retirar uma única vez a interseção dos 90.','Trinta e cinco ignora parte dos formulários presentes em apenas um grupo.']);
L('condicional','Considere como verdadeira a regra: “Se o mapa foi validado, então o setor foi liberado”. Sabendo apenas que o setor não foi liberado, qual conclusão lógica decorre da regra?',
 ['O mapa não foi validado.','O mapa foi validado, mas houve atraso.','Todo mapa não validado jamais será liberado.','O setor foi liberado por outro supervisor.','Nada pode ser inferido sobre a validação.'],
 ['Pela contrapositiva de P→Q, não Q implica não P: sem liberação, não houve validação no modelo dado.','P e não Q tornariam falsa a regra adotada como verdadeira.','A regra não afirma que não validação seja a única impossibilidade futura.','A conclusão contradiz o fato informado de que o setor não foi liberado.','A contrapositiva permite, sim, inferir a ausência de validação.']);
L('razão e proporção','Dois grupos dividiram 168 visitas na razão 4:3. Após a redistribuição, 12 visitas passaram do grupo maior ao menor. Qual passou a ser a diferença entre as cargas?',
 ['0','12','24','36','48'],
 ['As cargas iniciais são 96 e 72; depois da transferência ficam 84 e 84, portanto diferença zero.','Doze é o volume transferido, não a diferença final entre os grupos.','Vinte e quatro era a diferença antes da transferência, que cai em 24.','Trinta e seis não corresponde nem à razão inicial nem às cargas posteriores.','Quarenta e oito ignora que transferir 12 reduz a diferença em 24.']);
L('probabilidade','Uma caixa contém 5 fichas verdes e 3 amarelas. Duas fichas são retiradas sem reposição. Qual a probabilidade de terem cores diferentes?',
 ['15/28','15/56','25/64','3/8','5/8'],
 ['Há dois caminhos: verde-amarela (5/8×3/7) e amarela-verde (3/8×5/7); a soma é 30/56=15/28.','Conta apenas uma das duas ordens possíveis de cores diferentes.','Usa como se houvesse reposição e ainda desconsidera a composição após a primeira retirada.','Três oitavos é só a chance de amarelo na primeira retirada.','Cinco oitavos é só a chance de verde na primeira retirada.']);
L('média aritmética','A média de quatro tempos de entrevista foi 18 minutos. Um quinto atendimento, de 28 minutos, foi acrescentado. Qual a nova média dos cinco tempos?',
 ['20 minutos','19 minutos','21 minutos','22 minutos','23 minutos'],
 ['A soma inicial é 4×18=72; somando 28, obtém-se 100, e 100/5=20 minutos.','Dezenove não inclui corretamente os dez minutos acima da média antiga diluídos em cinco casos.','Vinte e um resultaria de soma total 105, não 100.','Vinte e dois extrapola o efeito de apenas um atendimento mais longo.','Vinte e três ignora que quatro dos cinco tempos tinham média 18.']);
L('sequências','Uma sequência é construída somando números ímpares consecutivos: 6, 9, 14, 21, 30. Qual é o próximo termo?',
 ['41','39','40','42','45'],
 ['As diferenças são 3, 5, 7 e 9; a próxima é 11, logo 30+11=41.','Trinta e nove repetiria o último incremento, que foi 9.','Quarenta exigiria incremento par, rompendo a sequência ímpar.','Quarenta e dois exigiria diferença 12, não a próxima ímpar.','Quarenta e cinco usaria 15, saltando dois incrementos esperados.']);
L('equações','Uma equipe registrou 7 formulários a mais que outra. Juntas registraram 83. Quantos formulários registrou a equipe com menos registros?',
 ['38','37','39','45','46'],
 ['Se a menor registrou x, então x+(x+7)=83; 2x=76 e x=38.','Trinta e sete levaria a soma 37+44=81, abaixo do total.','Trinta e nove levaria a soma 39+46=85, acima do total.','Quarenta e cinco é a carga da equipe maior, não da menor.','Quarenta e seis não satisfaz soma 83 nem diferença 7.']);
L('porcentagem','De 240 cadastros, 30% exigiram revisão. Após revisar um quarto desses cadastros, quantos ainda exigem revisão?',
 ['54','18','60','72','180'],
 ['Trinta por cento de 240 são 72; um quarto de 72 é 18, restando 72−18=54.','Dezoito é o número já revisado, não o saldo pendente.','Sessenta não corresponde a três quartos dos 72 que exigiam revisão.','Setenta e dois é o total inicialmente pendente, antes do trabalho.','Cento e oitenta corresponde aos que não exigiam revisão inicialmente.']);
L('geometria básica','Um terreno retangular mede 18 m por 12 m. Uma faixa de 2 m de largura contorna toda a parte interna, deixando um retângulo central. Qual a área central, em m²?',
 ['112','160','140','144','216'],
 ['A faixa retira 2 m de cada lado: o centro mede 14 m por 8 m; sua área é 112 m².','Cento e sessenta usa apenas uma redução de largura e esquece a outra dimensão.','Cento e quarenta não é produto das dimensões internas 14 e 8.','Cento e quarenta e quatro seria a área de um quadrado de 12 m, inexistente aqui.','Duzentos e dezesseis é a área total antes da faixa.']);
L('negação lógica','Qual é a negação de “Todos os mapas foram revisados e algum setor foi liberado”, considerando os quantificadores no universo mencionado?',
 ['Algum mapa não foi revisado ou nenhum setor foi liberado.','Nenhum mapa foi revisado e nenhum setor foi liberado.','Algum mapa foi revisado ou algum setor foi liberado.','Todos os mapas não foram revisados e algum setor não foi liberado.','Algum mapa não foi revisado e nenhum setor foi liberado.'],
 ['Negar A∧B produz não A∨não B; “não todos” é “algum não” e “não algum” é “nenhum”.','Exige que as duas partes sejam falsas, condição mais forte que a negação.','A frase pode ser verdadeira juntamente com a original e não a nega.','Altera os quantificadores e mantém uma conjunção que não equivale à negação.','Trocar a disjunção por conjunção exclui casos que também tornam a original falsa.']);
L('diagramas lógicos','Sabe-se que todo supervisor é servidor e que alguns servidores são motoristas. O que é necessariamente verdadeiro, sem outras premissas?',
 ['Todo supervisor é um dos servidores.','Algum supervisor é motorista.','Todo motorista é supervisor.','Nenhum supervisor é motorista.','Todo servidor é supervisor.'],
 ['A primeira inclusão é exatamente a premissa universal, independentemente da interseção com motoristas.','Os servidores motoristas podem estar fora do subconjunto dos supervisores.','Nada foi afirmado sobre inclusão dos motoristas no grupo de supervisores.','Também é possível que alguns supervisores sejam motoristas; a exclusão não foi dada.','A inclusão inversa não decorre de “todo supervisor é servidor”.']);
L('aritmética','Um posto usa caixas de 24 formulários. Foram preenchidos 196 formulários, e caixas abertas podem ficar parcialmente vazias. Qual o menor número de caixas necessárias?',
 ['9','8','10','11','12'],
 ['Oito caixas comportam 192, insuficientes; a nona acomoda os quatro formulários restantes.','Oito caixas faltariam quatro unidades para atingir 196.','Dez caixas caberiam, mas não seriam o número mínimo solicitado.','Onze caixas também excedem o mínimo, embora comportem o material.','Doze caixas aumentariam ainda mais a sobra sem necessidade.']);
L('frações','Três quintos de um lote de mapas já foram conferidos. Dos mapas restantes, metade foi conferida no turno seguinte. Qual fração do lote total ainda falta conferir?',
 ['1/5','2/5','3/10','1/2','4/5'],
 ['Após 3/5, restam 2/5; metade desse restante é 1/5, deixando outros 1/5 por conferir.','Dois quintos era a parte pendente antes do turno seguinte.','Três décimos não resulta de tomar metade de 2/5.','Metade foi aplicada ao restante, não ao lote inteiro.','Quatro quintos seria a parte já conferida após os dois turnos.']);
L('argumentação','Considere as premissas “Nenhum arquivo sem autorização pode ser divulgado” e “Este arquivo não tem autorização”. Qual conclusão respeita ambas, sem inverter a primeira regra?',
 ['Este arquivo não pode ser divulgado.','Todo arquivo autorizado deve ser divulgado.','Este arquivo poderá ser divulgado se for antigo.','Nenhum arquivo pode obter autorização posteriormente.','Todo arquivo não divulgado carece de autorização.'],
 ['O arquivo pertence ao conjunto dos sem autorização, que a regra exclui da divulgação.','A regra proíbe uma classe, mas não obriga a divulgação dos autorizados.','A idade do arquivo não aparece como exceção em nenhuma premissa.','As premissas não tratam da possibilidade de autorização futura.','A conclusão inverte a direção da implicação: pode haver outros motivos para não divulgar.']);
L('regra de três','Cinco agentes, trabalhando 6 horas por dia durante 4 dias, concluíram 360 verificações. No mesmo ritmo por agente-hora, quantas verificações fazem 4 agentes em 5 dias de 6 horas?',
 ['360','300','288','420','450'],
 ['O trabalho total inicial é 5×6×4=120 agente-horas, ou 3 verificações por agente-hora; o novo total também é 4×6×5=120.','Trezentas trataria a redução de agentes sem compensar os dias adicionais.','Duzentas e oitenta e oito decorre de razão incompleta entre os dois cenários.','Quatrocentas e vinte supera o resultado apesar de as agente-horas serem iguais.','Quatrocentas e cinquenta exigiriam ritmo maior que o mantido por hipótese.']);

// Noções de Administração — 20 questões.
A('sistemas abertos','Uma unidade de atendimento recebe novas demandas da população, ajusta a distribuição de agentes e observa se os prazos melhoraram. Qual sequência traduz melhor seu funcionamento como sistema aberto?',
 ['Entradas do ambiente, transformação interna, saídas e retorno sobre os resultados.','Entradas internas, isolamento do ambiente, saídas sem retorno.','Apenas resultados finais, sem depender de recursos ou demandas.','Somente decisões da chefia, sem informação dos usuários.','Controle de pessoas sem relação com a qualidade da entrega.'],
 ['Demandas são entradas; a organização do trabalho transforma recursos; o serviço é saída, e a avaliação fornece feedback.','Um sistema aberto troca informação com o ambiente, não se isola dele.','Resultados dependem de entradas e processos que a alternativa omite.','A reação de usuários compõe o retorno necessário aos ajustes.','Controle isolado não descreve fluxo completo de um sistema aberto.']);
A('planejamento','Uma coordenação define que reduzirá em 20% as pendências até dezembro, identifica recursos e responsáveis, mas ainda não executa ações. Qual função administrativa predomina?',
 ['Planejamento, por definir objetivo, prazo e meios antes da execução.','Direção, por supervisionar pessoas durante a execução.','Controle, por comparar resultado realizado com o padrão.','Organização, exclusivamente por separar documentos em pastas.','Avaliação final, por medir o impacto já produzido.'],
 ['Estabelecer meta, horizonte e meios é núcleo do planejamento; a execução e a medição vêm depois.','Ainda não há condução da equipe durante a ação descrita.','O resultado não ocorreu, portanto não pode ser comparado ao padrão.','Organização distribui recursos e atribuições, mas a ênfase é a definição prévia da meta.','Não existe impacto final medido nessa etapa.']);
A('organização','Depois de fixar a meta anual, a chefia distribui servidores entre postos, define quem aprova cadastros e estabelece canais de reporte. Qual função aparece de forma mais direta?',
 ['Organização dos recursos e responsabilidades para executar o plano.','Controle corretivo baseado em desvios já observados.','Planejamento estratégico de longo prazo ainda não formulado.','Motivação individual sem estrutura de tarefas.','Avaliação de impacto social da operação concluída.'],
 ['A chefia aloca pessoas, atribui papéis e define relações formais: tarefas típicas da organização.','Não há desvio medido nem correção posterior no enunciado.','A meta já foi estabelecida e a cena trata da estrutura para cumpri-la.','Motivação pode influir, mas não descreve a distribuição de autoridade.','A operação não foi concluída nem teve impacto mensurado.']);
A('direção','Uma equipe conhece suas tarefas, mas recebe orientações divergentes e perde prioridade. A chefia reúne os agentes, esclarece objetivos e acompanha a execução. Que função se destaca?',
 ['Direção, ao orientar e conduzir as pessoas na execução do trabalho.','Controle contábil, ao encerrar a prestação de contas.','Planejamento, apenas por redigir um documento futuro.','Arquivo, por classificar documentos permanentes.','Departamentalização, por criar novas unidades formais.'],
 ['Conduzir pessoas, comunicar prioridades e acompanhar execução caracterizam direção.','Não há encerramento de contas nem foco contábil.','O caso pede orientação presente, não só formulação prévia de plano.','Classificação documental não responde ao conflito de orientação.','Não se criaram departamentos nem se mudou a estrutura formal.']);
A('controle','A meta era concluir 400 registros; a unidade concluiu 340 e identificou atrasos de validação. Qual ação representa controle administrativo completo?',
 ['Comparar o resultado com a meta, investigar o desvio e ajustar a validação.','Repetir a meta sem consultar a execução observada.','Aumentar a meta para 500 a fim de ocultar o desvio.','Punir toda a equipe antes de verificar as causas do atraso.','Arquivar os números por serem inferiores ao planejado.'],
 ['Controle envolve estabelecer padrão, medir desempenho, comparar e agir sobre desvios identificados.','Repetir a meta não usa a informação de desempenho disponível.','Alterar a meta para encobrir resultado destrói a comparação.','Uma reação punitiva geral dispensa análise da causa específica.','Arquivar sem investigar impede a ação corretiva.']);
A('coordenação','Duas equipes visitam a mesma rua enquanto outra rua fica sem cobertura, embora cada equipe cumpra suas tarefas internas. Qual intervenção é propriamente de coordenação?',
 ['Integrar roteiros e responsabilidades entre equipes para eliminar sobreposição e lacuna.','Cobrar apenas mais velocidade de cada equipe, mantendo os roteiros.','Eliminar a conferência de ruas para reduzir reuniões.','Delegar o problema aos moradores sem combinar ações internas.','Trocar somente o nome das equipes nos relatórios.'],
 ['Coordenação articula atividades interdependentes, ajustando interfaces para o objetivo comum.','Maior velocidade pode duplicar ainda mais o esforço errado.','Sem conferência, a lacuna territorial tende a permanecer invisível.','A articulação do trabalho é responsabilidade organizacional.','Renomear equipes não altera as rotas ou cobertura real.']);
A('delegação','Uma supervisora transfere a conferência diária a um agente, define critérios e acompanha amostras. Qual afirmação distingue a delegação de abandono de responsabilidade?',
 ['A execução é atribuída ao agente, mas a supervisora mantém responsabilidade de acompanhar o resultado.','A supervisora perde toda responsabilidade assim que comunica a tarefa.','O agente recebe autoridade ilimitada para alterar os critérios.','A tarefa só é delegada se não houver qualquer controle posterior.','A autoridade formal sempre passa integralmente ao subordinado.'],
 ['Delegar atribui execução e autoridade compatível, mas não elimina o dever de supervisão de quem delega.','A responsabilidade gerencial não desaparece pela transferência da tarefa.','A autoridade delegada deve ter limites claros e relacionados à tarefa.','Acompanhamento é parte de uma delegação eficaz.','Não há transferência integral e irrestrita da autoridade formal.']);
A('eficiência e eficácia','Uma equipe alcançou as 300 visitas planejadas, mas usou o dobro de horas previsto. Como avaliar, respectivamente, eficácia e eficiência nesse caso?',
 ['Foi eficaz quanto à meta e menos eficiente quanto ao uso de horas.','Foi ineficaz e eficiente, porque trabalhou muitas horas.','Foi eficaz e necessariamente eficiente, pois cumpriu a meta.','Foi ineficaz porque a eficiência substitui a meta.','Nada pode ser dito sobre eficácia mesmo com a meta informada.'],
 ['Eficácia mede alcance do resultado; eficiência relaciona esse resultado aos recursos empregados.','Muitas horas não provam boa utilização de recursos nem ausência de resultado.','Cumprir a meta não garante uso econômico de horas.','A meta foi alcançada, portanto a eficácia no recorte informado existe.','O objetivo e o realizado foram explicitados, permitindo avaliar eficácia.']);
A('efetividade','Um posto concluiu todas as visitas e gastou pouco, mas parte relevante dos dados ficou inutilizável para orientar decisões públicas. Que dimensão foi mais diretamente comprometida?',
 ['Efetividade, porque a entrega não produziu plenamente o impacto útil esperado.','Apenas eficiência, pois baixo gasto sempre indica desperdício.','Apenas eficácia operacional, apesar de todas as visitas realizadas.','Autoridade formal, por inexistir chefe no enunciado.','Amplitude de controle, porque há muitos subordinados.'],
 ['Efetividade observa o efeito concreto da ação; volume e custo favoráveis não bastam se o produto não serve à finalidade.','Baixo gasto não é, por si, sinal de ineficiência.','A meta de visitas foi cumprida, embora sua utilidade final esteja comprometida.','A existência de chefia não é o ponto medido pelo caso.','O tamanho da equipe não foi informado nem explica a inutilidade dos dados.']);
A('unidade de comando','Um agente recebe ordens incompatíveis de dois superiores para o mesmo turno. Qual princípio organizacional é ameaçado e qual resposta tende a reduzir o conflito?',
 ['Unidade de comando; esclarecer a autoridade responsável pela prioridade daquela tarefa.','Amplitude de controle; ampliar indefinidamente o número de chefes.','Especialização; impedir qualquer divisão de tarefas.','Efetividade; medir apenas resultados no fim do mês.','Centralização; retirar do agente todos os equipamentos.'],
 ['Unidade de comando busca evitar ordens conflitantes sobre a mesma atuação, definindo linha clara de responsabilidade.','Amplitude trata da quantidade de subordinados por gestor, não resolve duas ordens divergentes.','Especialização distribui tarefas por competência e não elimina toda divisão.','Medir resultados depois não esclarece a prioridade imediata.','Retirar equipamentos não define quem orienta o trabalho.']);
A('atendimento ao público','Uma pessoa relata dificuldade com um formulário, mas o agente não tem competência para alterar o sistema. Qual conduta combina qualidade no atendimento e limite de atuação?',
 ['Ouvir a demanda, explicar o procedimento possível e encaminhar o problema ao canal competente.','Prometer alteração imediata do sistema para encerrar a conversa.','Ignorar a pessoa porque o problema não é da competência do agente.','Pedir a senha pessoal dela para tentar corrigir diretamente.','Registrar informação falsa para liberar o formulário provisoriamente.'],
 ['Atendimento adequado esclarece o que pode ser feito e encaminha o que depende de outra área, sem promessas indevidas.','Prometer solução fora da competência cria expectativa falsa.','O limite de competência não elimina dever de orientar e encaminhar.','Coletar senha de usuário compromete segurança e não é procedimento adequado.','Registro falso prejudica integridade dos dados e não soluciona a causa.']);
A('qualidade','Um serviço foi entregue rapidamente, mas vários registros precisaram ser refeitos por falta de conferência. Qual medida avalia melhor a qualidade sem confundi-la apenas com velocidade?',
 ['A taxa de retrabalho combinada com prazo e conformidade dos registros.','Somente o número bruto de registros por hora.','A quantidade de reuniões realizadas antes do turno.','O número de pessoas alocadas, sem observar o produto.','A velocidade máxima de uma única pessoa da equipe.'],
 ['Qualidade envolve atendimento a requisitos e utilidade da entrega; retrabalho e conformidade complementam a medida de prazo.','Produção rápida pode esconder defeitos e custo de correção.','Reuniões não medem diretamente qualidade do registro entregue.','Tamanho da equipe não informa precisão do resultado.','O caso de um indivíduo não substitui indicador do serviço.']);
A('documentação e arquivo','Um documento concluído precisa ser localizado meses depois para comprovar uma decisão. Qual prática favorece recuperação e rastreabilidade sem modificar o conteúdo?',
 ['Classificá-lo por critério definido, registrar sua localização e preservar a versão final.','Mudar seu título semanalmente para refletir quem o consultou.','Guardar apenas em pasta pessoal sem padrão de nomeação.','Eliminar metadados e datas para reduzir tamanho.','Substituir o original por memória oral de quem participou.'],
 ['Classificação, identificação e guarda da versão final permitem localizar o documento e comprovar seu histórico.','Renomeações arbitrárias dificultam localizar a versão estável.','Pasta pessoal isolada cria dependência de um usuário e baixa rastreabilidade.','Metadados e datas auxiliam identificação e prova de contexto.','Memória oral não substitui documentação preservada.']);
A('estrutura informal','O organograma prevê comunicação por chefias, mas agentes de setores diferentes trocam dicas espontaneamente para resolver dúvidas. O que esse segundo fluxo exemplifica?',
 ['Relações informais que coexistem com a estrutura formal.','Extinção automática do organograma formal.','Delegação legal de competência administrativa.','Criação obrigatória de um novo departamento.','Ausência completa de coordenação entre áreas.'],
 ['A rede espontânea de interação não depende das linhas oficiais e pode coexistir com elas.','Trocas informais não revogam a estrutura oficial da organização.','Compartilhar dicas não transfere competência formal de decisão.','Não há criação de departamento no exemplo.','A troca de informações pode até ajudar a coordenação.']);
A('centralização','Uma unidade exige autorização da direção até para repor material comum, gerando atrasos. Qual mudança caracteriza descentralização com controle preservado?',
 ['Permitir reposições locais dentro de limites e exigir prestação de contas.','Eliminar todas as regras e registros de compras.','Manter todas as decisões na direção, mas aumentar os formulários.','Permitir que qualquer pessoa aprove despesas sem teto.','Transferir apenas a culpa pelo atraso à equipe local.'],
 ['Descentralizar desloca decisões delimitadas para níveis próximos da execução, mantendo padrões e prestação de contas.','Ausência de regras não equivale a distribuição responsável de autoridade.','Decisão ainda concentrada não muda a centralização.','Autoridade irrestrita sem limites enfraquece o controle.','Culpa não é competência decisória nem recurso operacional.']);
A('planejamento tático','A direção fixa o objetivo institucional anual; uma gerência transforma esse objetivo em metas trimestrais por unidade e recursos necessários. Esse desdobramento é predominantemente:',
 ['Planejamento tático, que traduz a estratégia para áreas e horizontes intermediários.','Planejamento operacional de cada atendimento isolado.','Controle corretivo após o término da operação.','Apenas missão institucional, sem metas mensuráveis.','Arquivo corrente, por registrar os documentos da gerência.'],
 ['A gerência desdobra um objetivo amplo em metas e recursos por área, típico do nível tático.','O plano não se limita a tarefas individuais e diárias.','Não há resultado passado a corrigir, mas preparação do trimestre.','Metas trimestrais são mais específicas que uma missão geral.','Registrar o plano não transforma sua natureza em atividade de arquivo.']);
A('processo decisório','Há três alternativas de rota. A chefia conhece tempo, custo e risco de cada uma e precisa escolher segundo critérios definidos antes da comparação. Qual ordem evita preferência arbitrária?',
 ['Definir critérios e pesos, comparar as rotas e justificar a escolha pelos resultados.','Escolher a primeira rota e depois inventar critérios que a favoreçam.','Descartar os dados de custo porque tempo sempre prevalece.','Somar tempo e custo diretamente, ignorando unidades distintas.','Trocar os critérios sempre que uma alternativa perder.'],
 ['Critérios prévios tornam a comparação transparente e reduzem ajustes oportunistas ao resultado desejado.','Critérios definidos depois da escolha apenas racionalizam uma preferência.','Não há informação de que custo seja irrelevante no caso.','Grandezas diferentes requerem escala ou ponderação apropriada.','Mudar regras durante a comparação compromete a coerência da decisão.']);
A('comunicação e feedback','Após enviar orientação escrita, a chefia descobre interpretações distintas entre os postos. Qual medida fecha melhor o ciclo de comunicação?',
 ['Verificar o entendimento, esclarecer dúvidas e registrar a orientação final.','Reenviar o mesmo texto sem verificar a compreensão.','Presumir que os postos entenderam porque receberam a mensagem.','Punir imediatamente quem pediu esclarecimento.','Substituir orientações por boatos informais.'],
 ['Feedback verifica se a mensagem foi compreendida; esclarecimento e registro reduzem divergências futuras.','Repetição sem checagem pode reproduzir a mesma ambiguidade.','Recebimento da mensagem não demonstra compreensão uniforme.','Pedir esclarecimento é sinal útil para corrigir a comunicação.','Boatos não fornecem orientação controlada e rastreável.']);
A('motivação','Uma equipe compreende a meta, mas percebe que esforços diferentes recebem o mesmo retorno e não há critério de reconhecimento. Qual ação gerencial tende a melhorar a motivação com justiça?',
 ['Explicar critérios, dar feedback e reconhecer resultados verificáveis.','Prometer benefícios sem poder concedê-los.','Esconder critérios para evitar questionamentos.','Aumentar tarefas sem esclarecer a finalidade.','Usar apenas cobrança pública dos que tiveram pior resultado.'],
 ['Critérios claros e retorno sobre resultados tornam a relação entre esforço e reconhecimento mais compreensível.','Promessa inexequível prejudica confiança na gestão.','Opacidade dificulta percepção de justiça e direção do esforço.','Mais tarefas sem propósito não atacam o problema relatado.','Exposição punitiva não substitui avaliação e feedback justos.']);
A('indicadores','Uma chefia compara dois postos apenas pelo número de formulários, embora um atenda área extensa e outro, um bairro compacto. Qual análise é mais cuidadosa?',
 ['Considerar contexto, tempo, recursos e qualidade antes de atribuir diferença a desempenho individual.','Concluir que o posto com menos formulários é necessariamente menos dedicado.','Desconsiderar a extensão territorial por não constar do total bruto.','Usar somente o maior valor como meta universal para todas as áreas.','Punir o menor posto sem verificar se houve entrevistas mais longas.'],
 ['Indicadores precisam ser interpretados com condições de trabalho e qualidade para evitar comparação enganosa.','O volume isolado não prova dedicação de pessoas.','Diferenças de deslocamento podem alterar capacidade de atendimento.','Meta igual sem ajuste de contexto pode ser injusta e ineficaz.','A ação corretiva exige investigar causas, inclusive duração das entrevistas.']);

// Situações gerenciais — 20 questões.
G('priorização','Três ocorrências chegam simultaneamente: falha que impede a coleta em dois postos, pedido de material para a próxima semana e dúvida pontual já documentada. Com recursos limitados, que sequência é mais defensável?',
 ['Conter a falha operacional, programar o material e responder à dúvida pelo procedimento existente.','Atender primeiro o pedido para a próxima semana, por ter prazo maior.','Resolver a dúvida pontual antes de verificar a paralisação dos postos.','Distribuir a equipe igualmente entre as três demandas sem avaliar impacto.','Suspender todas as decisões até que as três tenham a mesma urgência.'],
 ['Impacto imediato e urgência justificam tratar a paralisação primeiro, preservando tratamento planejado das demais.','Prazo distante não supera bloqueio atual de duas unidades.','Dúvida com procedimento conhecido pode receber resposta sem consumir prioridade máxima.','Divisão igual ignora diferença de impacto e criticidade.','A espera prolonga a falha sem benefício decisório.']);
G('feedback construtivo','Um agente cometeu dois erros de lançamento. O supervisor deseja corrigi-los sem desmotivar a equipe. Qual abordagem é mais útil?',
 ['Mostrar os registros específicos, explicar o critério correto e combinar nova conferência.','Afirmar diante de todos que o agente é desatento, sem citar registros.','Corrigir silenciosamente os dados e nunca informar o agente.','Dar apenas elogios para evitar desconforto, mantendo os erros.','Transferir o agente de área sem explicar o motivo da mudança.'],
 ['Feedback específico sobre comportamento e critério permite aprendizado e acompanhamento sem rotular a pessoa.','Rótulo pessoal e exposição pública não esclarecem como corrigir.','Correção silenciosa mantém a causa do erro desconhecida.','Elogio sem apontar falha não repara a qualidade do registro.','Transferência opaca não orienta a melhoria da execução.']);
G('gestão de conflitos','Dois postos disputam o mesmo veículo no mesmo horário e ambos alegam prioridade. A chefia dispõe de dados sobre distância, prazo e transporte alternativo. Qual ação favorece solução cooperativa?',
 ['Ouvir ambos, explicitar critérios, ajustar horários ou alternativas e registrar o acordo.','Decidir pela equipe que falou primeiro, sem verificar necessidade.','Prometer o veículo a ambos para evitar conflito imediato.','Deixar que os grupos disputem a chave no dia da viagem.','Impedir qualquer deslocamento até o fim do mês.'],
 ['A negociação usa necessidades e restrições reais para construir decisão verificável e reduzir recorrência.','Ordem de reclamação não é critério de impacto ou urgência.','Promessas incompatíveis criam conflito maior na execução.','Disputa informal não resolve alocação de recurso compartilhado.','Bloqueio geral prejudica os dois postos sem explorar alternativas.']);
G('delegação','Uma gestora delega análise de pendências, mas os agentes não sabem até que valor podem decidir sem consulta. Qual ajuste é necessário para tornar a delegação segura?',
 ['Definir escopo, limites de decisão, indicadores e canal de escalonamento.','Afirmar que a decisão delegada não requer qualquer prestação de contas.','Deixar os limites implícitos para medir iniciativa da equipe.','Exigir consulta para todo caso, inclusive os expressamente delegados.','Transferir autoridade total sem relação com a análise de pendências.'],
 ['Delegação eficaz combina autoridade compatível, limites claros e acompanhamento de resultados.','Prestação de contas permanece necessária mesmo após delegar.','Ambiguidade sobre limites aumenta decisões inconsistentes.','Consulta em todos os casos esvazia a autonomia concedida.','Autoridade ilimitada não é exigida nem prudente para tarefa específica.']);
G('liderança situacional','Uma equipe experiente domina o procedimento, mas perdeu autonomia porque o supervisor revisa cada passo. Qual mudança gerencial é mais coerente com essa maturidade?',
 ['Ampliar autonomia dentro de metas e acompanhar resultados em pontos combinados.','Aumentar a instrução minuciosa para cada ato já dominado.','Retirar objetivos e permitir que cada agente invente critérios.','Deixar de monitorar resultados porque a equipe é experiente.','Trocar todos os agentes para reiniciar o treinamento.'],
 ['Equipe competente pode receber mais autonomia, sem abandonar objetivos ou pontos de controle.','Microgerenciamento de rotina dominada consome tempo e inibe iniciativa.','Autonomia não significa ausência de padrão e meta.','Acompanhamento de resultados continua necessário.','Substituição integral não responde ao excesso de supervisão.']);
G('avaliação de desempenho','Um avaliador registra apenas o último erro de um servidor, ignorando meses de trabalho consistente. Qual medida melhora a avaliação?',
 ['Usar critérios definidos e evidências de todo o período, incluindo acertos e dificuldades.','Manter a última impressão porque é a mais recente.','Avaliar apenas a popularidade do servidor com colegas.','Retirar todos os registros de erro da avaliação.','Igualar todas as notas para não precisar justificar resultados.'],
 ['Período completo e evidências reduzem viés de recência e apoiam devolutiva justa.','Fato recente não representa necessariamente todo o desempenho.','Popularidade não substitui critérios ligados ao trabalho.','Erros relevantes devem ser considerados junto com resultados positivos.','Notas idênticas sem análise impedem reconhecer diferenças reais.']);
G('controle preventivo','Antes de iniciar uma nova etapa, o supervisor confere se há mapas, baterias e treinamento mínimo em todos os postos. Qual é a natureza principal desse controle?',
 ['Preventiva, porque busca evitar falhas antes da execução.','Concomitante, pois mede somente o trabalho em andamento.','Corretiva, pois repara resultado já entregue.','Finalística, porque dispensa verificação posterior.','Contábil, porque envolve necessariamente registro financeiro.'],
 ['A checagem prévia detecta falta de condições para operar e permite corrigir antes do início.','O trabalho da etapa ainda não está em andamento.','Não há produto final defeituoso a reparar.','Prevenção não elimina controles durante e depois da execução.','Baterias e treinamento não tornam o controle necessariamente financeiro.']);
G('controle corretivo','Uma auditoria encontra registros duplicados já transmitidos. Qual resposta expressa controle corretivo e aprendizado, sem apenas apagar sintomas?',
 ['Corrigir os registros conforme protocolo, localizar a origem da duplicação e ajustar o processo.','Excluir todos os registros da semana para garantir que não haja duplicados.','Ignorar os duplicados por já terem sido transmitidos.','Alterar apenas o relatório agregado e preservar dados inconsistentes.','Cobrar velocidade maior da equipe sem examinar o mecanismo de duplicação.'],
 ['Controle corretivo lida com falha detectada e com sua causa para evitar repetição.','Exclusão em massa sacrifica registros válidos e não identifica a causa.','Transmissão não transforma registro duplicado em dado correto.','Maquiar o agregado mantém a inconsistência na base.','Velocidade não substitui investigação do fluxo que duplicou dados.']);
G('tomada de decisão','Uma chefia dispõe de prazo curto e informações incompletas para escolher entre dois locais de apoio. Qual procedimento reduz risco sem exigir certeza impossível?',
 ['Identificar premissas críticas, comparar opções disponíveis, documentar a escolha e prever revisão.','Aguardar informação perfeita mesmo depois de perder o prazo.','Escolher aleatoriamente e esconder as incertezas da equipe.','Ignorar riscos por não haver tempo de fazer cálculo exato.','Decidir pelo local preferido sem confrontar nenhuma restrição.'],
 ['Sob incerteza, critérios explícitos e revisão posterior tornam a decisão justificável e ajustável.','Esperar certeza absoluta pode inviabilizar o objetivo no prazo.','Escolha aleatória sem transparência não usa os dados existentes.','Incerteza aumenta a importância de mapear riscos essenciais.','Preferência pessoal isolada não compara capacidade e limites dos locais.']);
G('metas SMART','Uma coordenação afirma: “Vamos melhorar muito a qualidade logo”. Qual formulação transforma essa intenção em meta mais verificável?',
 ['Reduzir de 12% para 6% os formulários devolvidos por erro até o fim do próximo mês.','Fazer o possível para que ninguém reclame algum dia.','Ter a melhor equipe do país sem indicador nem prazo.','Melhorar continuamente, independentemente de medida.','Eliminar todas as falhas imediatamente, sem verificar a situação inicial.'],
 ['Valor inicial, alvo, indicador e prazo tornam a meta específica e mensurável; a viabilidade ainda deve ser avaliada.','“Fazer o possível” não define resultado nem horizonte.','Comparação nacional sem critério observável não orienta execução.','Melhoria sem medida ou prazo é intenção, não meta operacional.','Zero falhas instantâneas ignora base, prazo e factibilidade.']);
G('indicadores de desempenho','Um posto aumentou o número de entrevistas, mas também duplicou a taxa de formulários devolvidos para correção. Qual leitura combina volume e qualidade?',
 ['O aumento de volume deve ser lido junto à taxa de retrabalho antes de afirmar ganho líquido.','O volume maior prova, por si, qualidade superior.','A devolução é irrelevante porque a entrevista aconteceu.','Uma taxa de erro maior sempre significa mais produtividade líquida.','É impossível avaliar qualquer aspecto porque há dois indicadores.'],
 ['Volume e retrabalho captam dimensões distintas; ganhar quantidade pode aumentar custo e atrasar a entrega útil.','Apenas contagem não demonstra conformidade ou utilidade do dado.','Devolução exige trabalho adicional e afeta qualidade.','Erro maior não garante produtividade efetiva.','Os dois indicadores permitem avaliação mais informada, não menos.']);
G('comunicação ascendente','Agentes observam que uma orientação central produz erros recorrentes, mas receiam relatá-los. Qual mecanismo fortalece a comunicação ascendente?',
 ['Abrir canal de relato com retorno sobre providências, sem punição pelo apontamento fundamentado.','Enviar somente ordens de cima para baixo e proibir dúvidas.','Exigir que problemas sejam comunicados apenas depois da prova final.','Atribuir automaticamente culpa ao primeiro agente que avisou.','Eliminar o registro de ocorrências para reduzir indicadores negativos.'],
 ['Comunicação ascendente permite que informação da execução chegue a quem decide e volte como resposta.','Fluxo apenas descendente oculta sinais de falhas do procedimento.','Atrasar relatos prolonga erros que poderiam ser corrigidos.','Punição do mensageiro desestimula comunicação de riscos reais.','Apagar ocorrências não elimina o problema operacional.']);
G('gestão de riscos','Uma unidade depende de um único equipamento para transmitir os dados no último dia. Qual planejamento trata o risco sem presumir que a falha ocorrerá?',
 ['Estimar probabilidade e impacto, preparar alternativa e testar a recuperação antes do prazo.','Comprar outro equipamento sem verificar custo, compatibilidade ou necessidade.','Ignorar a possibilidade porque o aparelho nunca falhou.','Parar a coleta desde já para evitar depender da transmissão.','Aguardar a falha e somente então procurar acesso à rede.'],
 ['Risco combina possibilidade de falha e consequência; contingência testada reduz o impacto se o evento ocorrer.','Recurso extra pode ajudar, mas decisão sem análise não constitui plano completo.','Histórico sem falha não torna a probabilidade nula.','Paralisação antecipada não é resposta proporcional ao risco descrito.','A reação apenas após o último prazo pode não permitir recuperação.']);
G('trabalho em equipe','Uma tarefa depende de conferência por um grupo e transmissão por outro. Ambos cumprem seus indicadores locais, mas a entrega final atrasa. Que intervenção ataca a interface?',
 ['Definir passagem, prazo e confirmação de recebimento entre os grupos.','Cobrar apenas a taxa individual de cada grupo, sem tratar a transição.','Unificar os relatórios finais sem alterar o fluxo de trabalho.','Suspender a conferência para acelerar toda transmissão.','Impedir comunicação direta entre grupos para evitar divergência.'],
 ['O gargalo está na passagem entre etapas; acordo de entrega e confirmação torna a dependência administrável.','Indicadores isolados podem esconder atraso entre equipes.','Juntar relatórios depois não corrige a transferência operacional.','Eliminar controle de qualidade cria outros defeitos.','Bloquear comunicação dificulta resolução da interface.']);
G('capacitação','Depois de treinamento expositivo, a equipe ainda erra um passo raro mas crítico. Qual reforço tende a produzir aprendizagem operacional verificável?',
 ['Simular o passo em casos reais, observar execução e oferecer feedback específico.','Repetir apenas a leitura dos slides sem prática.','Supor que presença no treinamento comprova domínio.','Punir todo erro sem mostrar o procedimento correto.','Retirar o passo do processo mesmo sendo crítico.'],
 ['Prática contextualizada e feedback evidenciam se o agente consegue aplicar o procedimento quando necessário.','Leitura isolada não testa desempenho na tarefa rara.','Participação é evidência de presença, não de competência adquirida.','Punição sem instrução não ensina sequência correta.','A criticidade descrita impede simplesmente omitir o passo.']);
G('responsabilidade e autoridade','Uma coordenadora responde por uma meta, mas não pode aprovar recursos nem ajustar escalas. Que desalinhamento prejudica seu desempenho?',
 ['Responsabilidade por resultado sem autoridade compatível sobre meios necessários.','Autoridade excessiva por responder por uma meta mensurável.','Ausência de objetivos, pois a meta foi explicitada.','Excesso de descentralização, pois toda decisão está com ela.','Conflito de arquivos, porque não há classificação documental.'],
 ['A responsabilidade exige acesso a decisões e recursos proporcionais; sem meios, a cobrança perde efetividade.','Não há poder excessivo; o caso afirma falta de competência decisória.','A meta existe, embora faltem meios para alcançá-la.','Decisões estão concentradas fora da coordenadora, não nela.','Arquivo não é a variável limitante informada no enunciado.']);
G('negociação','Duas equipes querem o mesmo espaço de treinamento. Uma precisa dele pela manhã, outra somente à tarde, mas ambas pediram o dia inteiro por precaução. Qual solução explora os interesses reais?',
 ['Dividir o uso por turno, confirmando necessidades e horários de preparação.','Dar o dia inteiro à equipe que formalizou primeiro o pedido.','Sortear uma equipe e deixar a outra sem espaço.','Negar o espaço a ambas para evitar reclamações.','Exigir que cada equipe mantenha o pedido integral, sem diálogo.'],
 ['Ao separar posições iniciais de necessidades concretas, o compartilhamento por turno pode atender ambos os interesses.','Ordem de formalização não aproveita a compatibilidade revelada.','Sorteio ignora que os horários necessários não coincidem.','Negação total desperdiça recurso disponível.','Insistir nas posições impede encontrar solução conjunta.']);
G('qualidade em serviços','Um posto responde rápido a reclamações, mas os mesmos problemas retornam semanalmente. Qual mudança é mais alinhada com melhoria contínua?',
 ['Investigar causas recorrentes, ajustar o processo e medir a reincidência.','Contar respostas enviadas como único sinal de solução definitiva.','Apagar reclamações antigas ao final de cada semana.','Aumentar a velocidade de resposta sem alterar a causa.','Trocar o nome do canal para parecer um serviço novo.'],
 ['Melhoria contínua trata causas e verifica se a mudança reduziu recorrência, não apenas prazo da resposta.','Responder não demonstra que a falha deixou de ocorrer.','Apagar histórico destrói a evidência do problema repetido.','Velocidade pode melhorar atendimento, mas não elimina causa sistêmica.','Mudança de nome não modifica a entrega ao usuário.']);
G('prestação de contas','Uma chefia delegou compras de baixo valor. Ao fim do mês, recebe apenas o total gasto, sem comprovantes nem relação com as necessidades atendidas. O que falta à prestação de contas?',
 ['Evidência das despesas e relação entre recursos usados, autorização e resultados obtidos.','Apenas um número maior para demonstrar que houve atividade.','A assinatura de todos os moradores atendidos, mesmo sem relação com compras.','A eliminação dos limites de compra previamente delegados.','Somente o nome do responsável, sem documentos de suporte.'],
 ['Prestação de contas exige rastreabilidade do gasto e avaliação de sua aderência à finalidade delegada.','Volume gasto não prova conformidade nem utilidade.','Assinaturas irrelevantes não substituem comprovantes e justificativas.','Limites de delegação ajudam, e não atrapalham, o controle.','Identificação isolada da pessoa não demonstra legitimidade das despesas.']);
G('gestão de mudanças','Um novo procedimento é tecnicamente correto, mas a equipe o abandona porque desconhece a razão da mudança e não recebeu prática. Qual implantação tende a aumentar adesão?',
 ['Explicar o problema resolvido, demonstrar o procedimento, treinar e recolher dificuldades de execução.','Enviar ordem lacônica e presumir que todos inferirão os motivos.','Proibir perguntas até que a adesão seja total.','Trocar simultaneamente todos os procedimentos sem priorizar aprendizagem.','Medir apenas quantas mensagens foram enviadas pela chefia.'],
 ['Sentido da mudança, capacitação e feedback reduzem incerteza e revelam obstáculos reais à adoção.','Ordem sem contexto ou prática não resolve as causas de abandono descritas.','Bloquear dúvidas impede detectar falhas de compreensão.','Múltiplas mudanças simultâneas podem ampliar dificuldade de aprendizagem.','Quantidade de mensagens não comprova aplicação correta do novo processo.']);

// Conhecimentos Técnicos — 15 questões apoiadas na apostila oficial.
T('setor censitário',20,'Um agente recebe como área de trabalho um setor censitário. Qual afirmação relaciona corretamente essa área com a coleta, sem confundi-la com município ou estabelecimento?',
 ['É a unidade territorial de coleta do IBGE, com contorno que delimita o trabalho do agente.','É sempre equivalente ao município inteiro em que o agente atua.','É uma propriedade rural com matrícula imobiliária única.','É toda área observável na tela do mapa, mesmo fora do contorno.','É a equipe de recenseadores, independentemente de área geográfica.'],
 ['A apostila define setor como a menor área geográfica estabelecida pelo IBGE e unidade territorial de coleta.','Um município pode conter muitos setores; os limites não são equivalentes.','Propriedade e setor são categorias diferentes: uma produtiva/patrimonial, outra territorial de coleta.','A representação cartográfica pode mostrar referências externas ao perímetro.','Setor identifica área, não grupo de pessoas.']);
T('mapa e descritivo',20,'No verso do mapa há um texto que descreve todo o contorno do setor. Em uma bifurcação pouco clara, que uso dos dois instrumentos respeita a orientação técnica?',
 ['Confrontar a representação gráfica com o descritivo para reconhecer o limite real da área de coleta.','Presumir que qualquer estrada desenhada dentro do papel pertence integralmente ao setor.','Usar apenas o ponto mais próximo de deslocamento e descartar o texto.','Trocar o descritivo pelo endereço do primeiro morador encontrado.','Redesenhar o limite no dispositivo assim que a imagem parecer imprecisa.'],
 ['O mapa orienta visualmente, enquanto o descritivo define textualmente o contorno e auxilia no reconhecimento.','O mapa pode retratar elementos de referência que não compõem toda a área de trabalho.','Facilidade de deslocamento não substitui o limite documentado.','Endereço individual não descreve o perímetro setorial completo.','Recenseador não pode alterar perímetro por conta própria.']);
T('setores excluídos',30,'O perímetro externo de um setor rural envolve um núcleo que aparece na lista de “setores a serem excluídos”. Um entrevistado desse núcleo oferece informações ao recenseador rural. Como evitar duplicidade?',
 ['Não coletar ali como parte do setor rural, pois outro recenseador responde pelo setor interno.','Aceitar os dados porque o núcleo está dentro do contorno externo.','Coletar apenas estabelecimentos produtivos e ignorar os demais endereços.','Somar o núcleo ao setor rural se a entrevista já começou.','Apagar a anotação de exclusão após confirmar a existência do núcleo.'],
 ['A indicação de exclusão retira o setor interno da responsabilidade do recenseador do setor envolvente.','Contorno externo, sozinho, não incorpora territórios expressamente excluídos.','A exclusão é territorial e não depende do tipo de atividade observada.','O início de conversa não transfere competência territorial.','Apagar referência oficial aumenta o risco de dupla coleta ou omissão.']);
T('limites do setor',30,'Um caminho de campo não coincide claramente com a descrição recebida, e dois recenseadores discordam sobre a divisa. Qual decisão protege a integridade da cobertura?',
 ['Comunicar a inconsistência imediatamente à supervisão e preservar o perímetro oficial até orientação.','Dividir a área pela metade por acordo informal entre os recenseadores.','Coletar ambos os lados nos dois setores e deduplicar depois.','Deixar toda a faixa sem coleta para evitar conflito.','Mover o limite no mapa conforme a preferência do morador mais próximo.'],
 ['A apostila manda comunicar dificuldades de limite à supervisão e proíbe ao recenseador alterar o perímetro.','Acordo informal não redefine área oficial de responsabilidade.','Coleta dupla cria risco de duplicidade e distorce a cobertura.','Omissão deliberada deixa área sem responsável.','Preferência individual não substitui documentação e decisão da supervisão.']);
T('CNEFE',43,'Um imóvel rural tem nome oficial da estrada, mas também um apelido conhecido no povoado. O agente pretende facilitar localização futura. Qual registro segue a prioridade do CNEFE?',
 ['Usar o endereço formal como base e acrescentar referência local quando ela ajudar a individualizar a unidade.','Trocar sempre o nome oficial pelo apelido, mesmo que o primeiro esteja correto.','Registrar apenas o CEP, dispensando os demais componentes.','Usar o nome do morador como logradouro para acelerar a busca.','Ignorar qualquer referência local, mesmo quando o endereço formal não distingue o imóvel.'],
 ['O padrão prioriza endereço formal e admite referência reconhecida quando necessária à individualização e localização.','Apelido não substitui automaticamente um logradouro oficial disponível.','CEP, sozinho, não individualiza endereço rural específico.','Identificar pessoa em componente do endereço fere a orientação de sigilo.','Referências locais são úteis quando o endereço formal não basta.']);
T('ponto de referência',47,'Uma unidade não tem número nem complemento que permita achá-la; fica depois de uma ponte permanente. Qual anotação é mais apropriada?',
 ['“Primeira construção após a ponte”, como ponto de referência estável.','“Casa da senhora que respondeu ao questionário”, identificando a pessoa.','Um número inventado para preencher a lacuna no endereço.','Apenas “zona rural”, sem referência individualizadora.','O nome do recenseador responsável pelo setor.'],
 ['Sem número ou complemento localizador, o ponto de referência é obrigatório; marco físico estável ajuda a reencontrar o local.','Identificação de pessoas em componentes do endereço viola sigilo.','Número fictício cria dado incorreto e não melhora localização.','Expressão genérica não individualiza a unidade.','Nome do agente não é componente localizador do imóvel.']);
T('abordagem inicial',53,'Ao ver uma área com árvores, o recenseador conclui visualmente que se trata de pomar comercial. Qual procedimento evita classificar por aparência uma unidade talvez não recenseável?',
 ['Perguntar pela atividade e aplicar o questionário de abordagem inicial para definir a classificação.','Registrar automaticamente o pomar como estabelecimento por ter árvores.','Excluir automaticamente a unidade por parecer pequena.','Usar apenas fotografia externa para preencher os quesitos de produção.','Perguntar à propriedade vizinha e dispensar contato com o informante.'],
 ['A apostila diz que não se determina a atividade recenseável olhando de fora; a abordagem inicial orienta a classificação.','Árvores podem ser lazer ou outra situação, sem produção enquadrável.','Tamanho aparente não elimina unidade produtiva do conceito.','Fotografia não informa finalidade nem período de exploração.','A informação do vizinho não substitui a abordagem do responsável.']);
T('produção de subsistência',53,'Uma família consome quase toda a produção da horta e troca pequena parte por produtos necessários à casa. Segundo a definição da apostila, qual análise é adequada?',
 ['A troca eventual não afasta a subsistência se a atividade sustenta majoritariamente as necessidades vitais.','Qualquer troca transforma toda a produção em atividade exclusivamente comercial.','A subsistência exige que nada seja vendido ou trocado em hipótese alguma.','A classificação depende apenas da extensão da horta em hectares.','A família só pode produzir para subsistência se tiver documento de propriedade.'],
 ['A apostila admite venda ou troca eventual e enfatiza a dependência alimentar total ou majoritária da família.','Troca pontual não altera, por si, o objetivo predominante.','Proibição absoluta de troca contraria a definição expressa.','Área física não determina isoladamente a finalidade produtiva.','Título da terra não é requisito do conceito de subsistência.']);
T('conceito de estabelecimento',55,'Uma associação mantém produção aquícola para sustento de associados em área urbana pequena. Qual argumento é compatível com o conceito censitário?',
 ['Pode ser estabelecimento pela exploração aquícola, apesar de porte, forma jurídica e local.','Não pode ser estabelecimento porque associação não é pessoa física.','Não pode ser estabelecimento porque fica em área urbana.','Só pode ser estabelecimento se vender toda a produção.','Só pode ser estabelecimento se atingir valor mínimo de mercado.'],
 ['O conceito abrange exploração aquícola, inclusive para subsistência, sem exigência isolada de porte, natureza jurídica ou área rural.','A forma jurídica não exclui a unidade de produção.','Localização urbana não é impedimento por si só.','Produção para sustento também integra a finalidade prevista.','Valor da produção não é limite geral do conceito.']);
T('produtor sem área',57,'Um extrativista recolhe castanha em área disponível temporariamente e conduz a atividade por conta própria, sem possuir terra delimitada. Qual registro evita omissão?',
 ['Investigar e registrar a atividade como possível produção de produtor sem área, aplicando o questionário.','Ignorar a atividade porque falta matrícula imobiliária em seu nome.','Atribuir toda a produção automaticamente ao dono da terra.','Classificar como atividade industrial apenas pela venda posterior.','Recensear somente se o extrativista morar permanentemente no local.'],
 ['A apostila cita extrativista em área alheia entre exemplos de produtor sem área e manda registrar sua atividade.','Propriedade formal não é exigida para esse enquadramento.','Condução própria não permite imputação automática ao titular da terra.','Venda posterior não converte a atividade extrativa em indústria.','Residência permanente não é condição apresentada para o produtor sem área.']);
T('propriedade e estabelecimento',60,'Uma mesma fazenda foi arrendada em duas partes; cada arrendatário decide a produção e administra seus recursos separadamente. Qual unidade deve orientar a investigação?',
 ['As explorações independentes, que podem constituir dois estabelecimentos na mesma propriedade.','A matrícula da fazenda, que obriga um único estabelecimento.','O endereço do proprietário, que substitui a gestão dos arrendatários.','A área maior apenas, porque a menor não pode ser estabelecimento.','Uma produção somada sem identificar responsáveis por cada exploração.'],
 ['Propriedade rural e estabelecimento são conceitos diferentes; produtores independentes podem formar unidades distintas.','Unicidade da matrícula não impõe unidade de gestão produtiva.','Titularidade do imóvel não define quem conduz cada exploração.','Tamanho não é condição geral para reconhecer estabelecimento.','Somar sem separar gestores pode ocultar unidades produtivas autônomas.']);
T('sede e setor',61,'Uma exploração ocupa partes de dois setores; a sede onde se administram os trabalhos está dentro da área do setor menor. Qual setor responde pelo recenseamento da unidade?',
 ['O setor da sede, mesmo que detenha a menor parte das terras.','O setor da maior área, sempre, mesmo havendo sede.','Os dois setores, cada um registrando a produção inteira.','O setor de residência particular do dono, ainda que fora da exploração.','Nenhum setor até que todas as terras estejam contínuas.'],
 ['Para estabelecimento em mais de um setor, prevalece o setor onde está a sede localizada na área da exploração.','Maior área só é critério subsidiário quando não há sede.','Duplicar a produção em dois setores distorce o levantamento.','Residência externa não se torna sede apenas por ser do proprietário.','A existência de limites setoriais não impede recensear a unidade.']);
T('áreas não contínuas',61,'Duas áreas descontínuas ficam no mesmo município e usam a mesma equipe, máquinas e administração. Que conjunto de condições permite considerá-las uma exploração única?',
 ['Município comum, recursos técnicos e humanos compartilhados e mesma administração, simultaneamente.','Apenas identidade do proprietário da terra, sem observar gestão ou equipe.','Somente uso das mesmas máquinas, mesmo em municípios diferentes.','Mesma administração, mesmo sem compartilhamento de recursos humanos.','Qualquer proximidade física, ainda que produtores diferentes conduzam as áreas.'],
 ['A apostila exige simultaneamente quatro condições para reunir áreas não contínuas em um estabelecimento.','Titularidade isolada não cobre recursos técnicos, humanos e administração.','Coincidência de máquinas não supera município diferente nem outros critérios.','Falta de equipe compartilhada impede a agregação pela regra.','Proximidade sem gestão e recursos comuns não basta.']);
T('continuidade territorial',62,'Uma linha férrea atravessa as terras de uma mesma unidade produtiva, sem mudança de administração. Qual decisão é compatível com a regra de continuidade da apostila?',
 ['Não dividir a exploração apenas pela ferrovia que corta a área.','Criar obrigatoriamente um estabelecimento de cada lado dos trilhos.','Recensear só a parte com sede e descartar a outra.','Tratar a faixa ferroviária como município distinto.','Transferir a produção de um lado para estabelecimento vizinho.'],
 ['Apostila afirma que ferrovias, rios e estradas cortando terras não caracterizam, por si, descontinuidade.','A separação física pela linha não obriga divisão da unidade produtiva.','A outra parte continua integrando a exploração informada.','Infraestrutura linear não cria nova divisão municipal no enunciado.','Não há base para atribuir produção ao vizinho.']);
T('exploração comunitária',66,'Numa comunidade, famílias trabalham juntas numa área e repartem uma produção coletiva; em outro núcleo, cada família decide e usa a própria produção. Como varia o questionário?',
 ['Um questionário para a produção coletiva; coleta individualizada no núcleo de decisões separadas.','Um questionário por família em ambos os núcleos, ignorando produção conjunta.','Um questionário único para ambos, porque as terras são comunitárias.','Nenhum questionário, porque exploração comunitária não é recenseável.','Um questionário por trabalhador, independentemente da unidade de produção.'],
 ['A apostila distingue produção coletiva conjunta, com um questionário, de produção individual, coletada por família.','Separar questionários na produção comum duplicaria a unidade coletiva.','Uso comunitário da terra não apaga decisões produtivas individuais.','Exploração comunitária é contemplada expressamente pelo material.','Número de trabalhadores não substitui a organização da produção.']);

// Informática ACI — 5 questões; Informática básica AOR — 5 questões.
I('backup e sincronização','Um computador sincroniza continuamente uma pasta com a nuvem. Um usuário exclui por engano um arquivo, e a exclusão é sincronizada. Qual medida melhora a capacidade de recuperação?',
 ['Manter backup versionado independente da sincronização e testar a restauração.','Confiar apenas na sincronização, pois ela impede toda exclusão.','Renomear a pasta após cada sincronização sem guardar versões.','Desativar todas as cópias locais e manter só o arquivo sincronizado.','Aumentar a velocidade da conexão para impedir erros do usuário.'],
 ['Sincronização replica mudanças, inclusive exclusões; cópia versionada oferece ponto anterior recuperável.','A sincronização não distingue erro humano de alteração legítima.','Renomear sem guardar histórico não recupera conteúdo excluído.','Dependência de uma única cópia aumenta o risco de perda.','Velocidade da rede não desfaz exclusão já propagada.']);
I('referência absoluta','Em uma planilha, a célula C2 contém =B2*$F$1. Ao copiar essa fórmula para C5, sem alterar a posição de F1, qual referência é esperada na nova célula?',
 ['=B5*$F$1','=B2*$F$4','=B5*F4','=B2*$F$1','=B5*$F5'],
 ['B2 é relativa e desce três linhas para B5; $F$1 fixa coluna e linha, permanecendo inalterada.','B2 deveria mudar e F1 não poderia passar a F4 por ser absoluta.','F4 perde a fixação da referência absoluta e altera o cálculo.','Manter B2 ignora a cópia relativa para a linha 5.','Em $F5, só a coluna ficaria fixa, não a linha como no original.']);
I('permissões de acesso','Uma pasta contém dados individuais e precisa ser consultada por cinco revisores, mas apenas dois devem corrigir os arquivos. Qual configuração aplica o menor privilégio?',
 ['Leitura para os cinco e edição apenas para os dois responsáveis pelas correções.','Edição irrestrita para toda a rede, para evitar solicitações de acesso.','Permissão de administrador para os cinco revisores.','Bloqueio total aos dois responsáveis pelas correções.','Um único usuário e senha compartilhados entre todos os revisores.'],
 ['Cada pessoa recebe somente o acesso necessário à sua tarefa, preservando rastreabilidade e integridade.','Escrita irrestrita amplia risco de alteração indevida.','Privilégios de administrador excedem a necessidade de consulta.','Quem corrige precisa de permissão de edição apropriada.','Credencial compartilhada dificulta atribuir ações a responsáveis.']);
I('CONT.SE','Na planilha, A1:A5 contém os valores 4, 7, 7, 9 e 12. O que retorna =CONT.SE(A1:A5;">=7")?',
 ['4','3','7','35','5'],
 ['Quatro células atendem ao critério: 7, 7, 9 e 12; CONT.SE conta ocorrências.','Três contaria valores distintos, mas as duas células com 7 contam separadamente.','Sete é um valor encontrado, não o número de células que satisfazem o critério.','Trinta e cinco é a soma dos valores elegíveis, operação diferente de CONT.SE.','Cinco incluiria o valor 4, que é menor que 7.']);
I('HTTPS','Um estudante vê um cadeado e HTTPS em uma página que pede senha. O que essa indicação permite concluir, sem presumir que a página seja legítima?',
 ['A conexão com aquele endereço usa criptografia, mas ainda é preciso verificar domínio e finalidade da página.','A página pertence necessariamente à instituição mencionada no conteúdo.','O cadeado garante que nenhuma informação será coletada pelo site.','HTTPS impede que o usuário acesse um domínio falso.','O navegador confirmou que todas as promessas comerciais da página são verdadeiras.'],
 ['HTTPS protege o tráfego com o servidor acessado; um site malicioso também pode obter certificado.','Identidade visual e certificado não provam vínculo com a instituição anunciada.','O próprio servidor pode receber dados enviados pelo usuário.','Domínios falsos podem operar com HTTPS válido.','Certificado não avalia a veracidade de alegações da página.']);
N('arquivos e cópias','Um operador precisa entregar uma cópia de planilha ao supervisor e continuar trabalhando no arquivo original. Qual ação mantém os dois arquivos disponíveis?',
 ['Copiar e colar o arquivo em local distinto, conferindo nomes e caminhos.','Recortar e colar o arquivo, pois o original permanecerá no local inicial.','Renomear apenas a extensão do arquivo para gerar outra cópia.','Excluir o original após abrir a planilha, sem salvar em outro lugar.','Criar um atalho e apagar o arquivo de origem.'],
 ['Copiar cria segunda instância, enquanto o original permanece no local inicial para edição.','Recortar prepara a movimentação; após colar, o original sai do primeiro local.','Renomear extensão altera o nome, não duplica o conteúdo.','Exclusão elimina o arquivo original, contrariando o objetivo.','Atalho depende do arquivo de origem e não é cópia independente.']);
N('operação offline','Durante a coleta sem sinal de rede, o aplicativo salva formulários no aparelho. Qual cuidado evita afirmar transmissão antes de ela ocorrer?',
 ['Verificar o status local, sincronizar quando houver conexão e conferir recibo ou log de envio.','Considerar todo formulário salvo localmente como recebido pelo servidor.','Apagar os dados locais assim que a bateria for recarregada.','Desligar a rede para garantir que o servidor já recebeu os dados.','Usar a hora da entrevista como prova suficiente de transmissão.'],
 ['Registro local e entrega ao servidor são etapas diferentes; log ou recibo confirma que a sincronização se concluiu.','Salvar offline não garante transmissão remota.','Apagar antes de confirmar entrega pode causar perda irreversível.','Rede desligada impossibilita envio naquele momento.','Horário da entrevista não demonstra recebimento pelo sistema central.']);
N('SOMA e MÉDIA','As células B1:B4 contêm 2, 4, 6 e uma célula vazia. Qual par de resultados é esperado para SOMA(B1:B4) e MÉDIA(B1:B4)?',
 ['12 e 4','12 e 3','12 e 6','8 e 4','4 e 12'],
 ['SOMA adiciona 2+4+6=12; MÉDIA ignora a célula vazia e divide 12 por três valores numéricos.','Dividir por quatro trataria indevidamente o vazio como zero na média.','Seis é o maior valor observado, não a média dos três.','O total 8 omite o valor 4 da soma.','Os resultados foram invertidos e não correspondem às funções.']);
N('perfis e senhas','Dois agentes usam o mesmo aparelho em turnos distintos. Qual prática permite atribuir ações a cada pessoa e restringir dados?',
 ['Usar perfis ou credenciais individuais, com permissões adequadas e bloqueio ao terminar o turno.','Compartilhar uma senha única anotada na capa do aparelho.','Manter sessão permanente aberta para dispensar identificação.','Copiar dados pessoais para aplicativos privados de mensagens.','Desabilitar o bloqueio de tela para acelerar a troca de turno.'],
 ['Credenciais individuais sustentam controle de acesso e rastreabilidade, e o bloqueio evita uso indevido entre turnos.','Senha compartilhada impede atribuir ações e expõe acesso.','Sessão aberta não distingue quem fez cada alteração.','Aplicativos privados ampliam exposição de dados pessoais.','Sem bloqueio, terceiros podem acessar o aparelho e seus dados.']);
N('planilhas e filtros','Uma planilha mostra apenas registros do setor 12 após aplicação de filtro. Qual afirmação evita confundir visualização com exclusão de dados?',
 ['As demais linhas podem continuar na planilha, apenas ocultas pela condição do filtro.','O filtro apagou definitivamente todas as linhas de outros setores.','O filtro transformou automaticamente os dados do setor 12 em gráfico.','A soma de qualquer coluna passa a ser zero por haver linhas ocultas.','A condição do filtro renomeia arquivos armazenados no computador.'],
 ['Filtro seleciona linhas para exibição sem necessariamente remover registros da base original.','Linhas não exibidas não são, por isso, deletadas.','Gráfico exige representação específica e não surge só por filtrar.','Cálculos dependem da fórmula utilizada; ocultação não impõe resultado zero.','Filtro de planilha não altera nome de arquivos do sistema.']);

